<?php
declare(strict_types=1);if(getenv('RUN_PLATFORM_AUTH_MARIADB_TESTS')!=='1'){echo "PlatformAdminAuthenticationMariaDb SKIPPED\n";exit;}require __DIR__.'/../vendor/autoload.php';use MiniErp\Infrastructure\ControlPlaneConnectionFactory;use MiniErp\Repositories\PlatformAdminRepository;use MiniErp\Services\PlatformAuthenticationService;$pdo=(new ControlPlaneConnectionFactory(__DIR__.'/../config.php'))->create();$pdo->beginTransaction();try{$erpHash=password_hash('ErpOnlyPass123',PASSWORD_DEFAULT);$pdo->prepare("INSERT INTO usuarios(nome,email,senha,status,tenant_id) VALUES('ERP TEST_ONLY','teste@example.com',?,'ativo',5)")->execute([$erpHash]);$repo=new PlatformAdminRepository($pdo);$service=new PlatformAuthenticationService($repo);try{$service->authenticate('teste@example.com','ErpOnlyPass123');throw new RuntimeException('ERP credential entered platform');}catch(DomainException $e){if($e->getMessage()==='ERP credential entered platform')throw$e;}$hash=password_hash('PlatformPass123',PASSWORD_DEFAULT);$id=$repo->create('Admin TEST_ONLY','admin@example.com',$hash);$identity=$service->authenticate('admin@example.com','PlatformPass123','127.0.0.1');if($identity->getUserId()!==$id||$identity->getRole()!=='SUPER_ADMIN')throw new RuntimeException('platform login');try{$service->authenticate('admin@example.com','wrong');throw new RuntimeException('wrong accepted');}catch(DomainException $e){if($e->getMessage()==='wrong accepted')throw$e;}for($i=0;$i<4;$i++)try{$service->authenticate('admin@example.com','wrong');}catch(DomainException){}try{$service->authenticate('admin@example.com','PlatformPass123');throw new RuntimeException('lock bypass');}catch(DomainException $e){if($e->getMessage()==='lock bypass')throw$e;}$repo->changePassword($id,password_hash('ChangedPass123',PASSWORD_DEFAULT),'TEST_ONLY');$changed=$service->authenticate('admin@example.com','ChangedPass123');if($changed->getUserId()!==$id)throw new RuntimeException('changed password');$pdo->prepare('UPDATE platform_admin_users SET active=0 WHERE id=?')->execute([$id]);try{$service->authenticate('admin@example.com','ChangedPass123');throw new RuntimeException('inactive accepted');}catch(DomainException $e){if($e->getMessage()==='inactive accepted')throw$e;}$actions=$pdo->query('SELECT action FROM platform_admin_audit_log')->fetchAll(PDO::FETCH_COLUMN);foreach(['ADMIN_CREATED','LOGIN_SUCCESS','LOGIN_FAILED','PASSWORD_CHANGED'] as $action)if(!in_array($action,$actions,true))throw new RuntimeException('audit '.$action);echo "PlatformAdminAuthenticationMariaDb OK\n";}finally{$pdo->rollBack();}
